<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
$app=new Nshir\App();$db=$app->db();$user=$app->user();$r=trim((string)($_GET['r']??''),'/');
function e(?string $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function u(string $r='',array $q=[]):string{$q=$r!==''?['r'=>$r]+$q:$q;return '/index2.php'.($q?'?'.http_build_query($q):'');}
function go(string $r='',array$q=[]):never{header('Location:'.u($r,$q));exit;}
function children(PDO$db,string$table,?int$parent):array{$sql="SELECT id,name,slug FROM $table WHERE ".($parent===null?'parent_id IS NULL':'parent_id=?')." AND is_active=1 ORDER BY sort_order,name";$q=$db->prepare($sql);$q->execute($parent===null?[]:[$parent]);return$q->fetchAll();}
function leaf(PDO$db,int$id):bool{$q=$db->prepare('SELECT 1 FROM categories WHERE parent_id=? AND is_active=1 LIMIT 1');$q->execute([$id]);return!$q->fetchColumn();}
function layout(string$title,string$body,?array$user):void{?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=e($title)?> | نشر - تجربة</title><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script></head><body><header class="top"><div class="wrap"><a class="logo" href="<?=u()?>"><b>ن</b>شر <small>تجريبي</small></a><nav class="nav"><?php if($user):?><a class="btn" href="<?=u('notifications')?>">الإشعارات</a><a class="btn" href="<?=u('profile')?>"><?=e($user['name'])?></a><a class="btn primary" href="<?=u('publish')?>">نشر إعلان</a><?php else:?><a class="btn" href="<?=u('login')?>">دخول</a><a class="btn primary" href="<?=u('register')?>">تسجيل</a><?php endif;?></nav></div></header><?=$body?></body></html><?php}
function cards(array$ads):string{ob_start();?><section id="ads" class="grid"><?php if(!$ads):?><div class="empty">لا توجد إعلانات هنا حتى الآن.</div><?php endif;foreach($ads as$a):?><article class="ad"><a href="<?=u('ad/'.$a['id'])?>"><?php if(!empty($a['image'])):?><div class="photo"><img loading="lazy" src="/ad/media/<?=e($a['image'])?>" alt=""></div><?php else:?><div class="photo">بدون صورة</div><?php endif;?><div class="info"><?php if($a['price']!==null):?><div class="price"><?=number_format((float)$a['price'])?> ر.س</div><?php endif;?><div class="title"><?=e($a['title'])?></div><div class="meta"><?=e($a['location_name']??'')?></div></div></a></article><?php endforeach;?></section><?php return ob_get_clean();}
function adQuery():string{return "SELECT a.id,a.title,a.price,l.name location_name,(SELECT path FROM ad_images i WHERE i.ad_id=a.id ORDER BY sort_order,id LIMIT 1) image FROM ads a JOIN locations l ON l.id=a.country_id";}

if($r==='logout'&&$_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$_SESSION=[];session_regenerate_id(true);go();}
if($r==='login'){
 if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$app->rateLimit('login',10,900);$q=$db->prepare('SELECT * FROM users WHERE email=? AND status="active"');$q->execute([mb_strtolower(trim($_POST['email']??''))]);$x=$q->fetch();if(!$x||!password_verify((string)($_POST['password']??''),$x['password_hash'])){$err='بيانات الدخول غير صحيحة.';}else{session_regenerate_id(true);$_SESSION['uid']=$x['id'];$db->prepare('UPDATE users SET last_login_ip=INET6_ATON(?) WHERE id=?')->execute([$app->clientIp(),$x['id']]);go();}}
 ob_start();?><main class="wrap hero"><h1>دخول</h1><?php if(isset($err)):?><p class="error"><?=e($err)?></p><?php endif;?><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input type="email" name="email" required></div><div class="field"><label>كلمة المرور</label><input type="password" name="password" required></div><button class="btn primary">دخول</button> <a href="<?=u('forgot')?>">نسيت كلمة المرور</a></form></main><?php layout('دخول',ob_get_clean(),$user);exit;
}
