 $countries=children($db,'locations',null);
 if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$app->rateLimit('register',5,3600);$email=mb_strtolower(trim($_POST['email']??''));$name=trim($_POST['name']??'');$pass=(string)($_POST['password']??'');$country=(int)($_POST['country_id']??0);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($name)<2||strlen($pass)<8||!$country){$err='تحقق من البيانات وكلمة المرور (8 خانات على الأقل).';}else{try{$geo=(new Nshir\GeoIp($app))->locate($app->clientIp());$city=(int)($geo['location']['id']??0);$token=bin2hex(random_bytes(32));$q=$db->prepare('INSERT INTO users(email,name,password_hash,country_id,city_id,registration_ip,verify_token_hash) VALUES(?,?,?,?,?,INET6_ATON(?),?)');$q->execute([$email,$name,password_hash($pass,PASSWORD_DEFAULT),$country,$city?:null,$app->clientIp(),hash('sha256',$token)]);$link=rtrim((string)(getenv('APP_URL')?:''),'/').u('verify',['token'=>$token]);Nshir\Mailer::send($email,'تفعيل حساب نشر',"مرحبًا $name\n\nلتفعيل حسابك:\n$link");$ok='تم إنشاء الحساب. راجع بريدك لتفعيل الحساب.';}catch(PDOException){$err='البريد مستخدم مسبقًا.';}}}
 ob_start();?><main class="wrap hero"><h1>حساب جديد</h1><?php if(isset($ok)):?><p class="success"><?=e($ok)?></p><?php else:?><?php if(isset($err)):?><p class="error"><?=e($err)?></p><?php endif;?><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input name="email" type="email" required></div><div class="field"><label>الاسم</label><input name="name" required maxlength="80"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>الدولة</label><select name="country_id" required><option value="">اختر</option><?php foreach($countries as$c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><button class="btn primary">إنشاء الحساب</button></form><?php endif;?></main><?php layout('تسجيل',ob_get_clean(),$user);exit;
