 if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$app->rateLimit('forgot',5,3600);$email=mb_strtolower(trim($_POST['email']??''));$q=$db->prepare('SELECT id,name FROM users WHERE email=? AND status="active"');$q->execute([$email]);if($x=$q->fetch()){$token=bin2hex(random_bytes(32));$db->prepare('UPDATE users SET reset_token_hash=?,reset_expires_at=DATE_ADD(NOW(),INTERVAL 1 HOUR) WHERE id=?')->execute([hash('sha256',$token),$x['id']]);$link=rtrim((string)getenv('APP_URL'),'/').u('reset',['token'=>$token]);Nshir\Mailer::send($email,'استعادة كلمة المرور',"رابط الاستعادة صالح لمدة ساعة:\n$link");}$ok=true;}
 ob_start();?><main class="wrap hero"><h1>استعادة كلمة المرور</h1><?php if(isset($ok)):?><p>إذا كان البريد مسجلًا فسيصلك رابط الاستعادة.</p><?php else:?><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input type="email" name="email" required></div><button class="btn primary">إرسال</button></form><?php endif;?></main><?php layout('استعادة كلمة المرور',ob_get_clean(),$user);exit;
}
