><?=nl2br(e($c['body']))?></p></div><?php endforeach;if($user):?><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><textarea name="comment" maxlength="2000" required></textarea></div><button class="btn primary">إضافة تعليق</button></form><?php else:?><a href="<?=u('login')?>">سجل الدخول للتعليق</a><?php endif;?></section></main><?php layout($ad['title'],ob_get_clean(),$user);exit;}
